var NeuroStatus = (() => {
    const e = hubUtils.escapeHtml, u = hubUtils.sourceHref;
    const get = (id) => neuroCompanyStatusData.companies.find(c => c.id === id);
    const refs = (c, ids) => `<span class="status-refs">${ids.map(id => { const s = c.sources.find(s => s.id === id); return s ? `<a href="${u(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Source: ${e(s.title)}">[${c.sources.indexOf(s) + 1}]</a>` : ''; }).join(' ')}</span>`;
    function render(id) { const c = get(id); if (!c)
        return ''; return `<section class="company-status" aria-label="Human studies and regulatory status"><header><span class="eyebrow">HUMAN STUDIES &amp; REGULATORY STATUS</span><span class="company-status-date">Checked ${e(c.checkedAt)}</span></header><span class="company-status-stage">${e(c.stage)}</span><h2>${e(c.headline)} ${refs(c, c.headlineRefs)}</h2><p>${e(c.summary)} ${refs(c, c.summaryRefs)}</p><p class="company-status-scope">${e(c.scope)} ${refs(c, c.scopeRefs)}</p><details><summary>Milestones, original sources &amp; review scope</summary><div class="company-status-facts">${c.facts.map(f => `<article>${f.date ? `<time>${e(f.date)}</time>` : ''}<h3>${e(f.title)}</h3><p>${e(f.text)} ${refs(c, f.refs)}</p></article>`).join('')}</div>${c.registry ? `<details class="company-status-registry"><summary>Inspect the ${c.registry.studies.length} directly sponsored registry records</summary><p>${e(c.registry.scope)} Snapshot fetched ${e(c.registry.checkedAt)}.</p><ul>${c.registry.studies.map(s => `<li><a href="https://clinicaltrials.gov/study/${e(s.nctId)}" target="_blank" rel="noopener noreferrer">${e(s.nctId)} · ${e(s.title)} ↗</a><span>${e(s.status.toLowerCase().split('_').join(' '))} · record updated ${e(s.statusUpdated)}</span><small>Study start: ${e(s.start.date)} (${e(s.start.type.toLowerCase())}) · Enrollment: ${s.enrollment.count} (${e(s.enrollment.type.toLowerCase())})</small></li>`).join('')}</ul></details>` : ''}${c.reviewNotes?.length ? `<aside class="company-status-review-scope"><strong>Access limits</strong>${c.reviewNotes.map(n => `<p>${e(n)}</p>`).join('')}</aside>` : ''}<ol class="company-status-sources">${c.sources.map(s => `<li><a href="${u(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a><small>${e(s.kind)} · ${s.published ? `source date ${e(s.published)}` : 'source undated'} · checked ${e(s.checkedAt)}</small><p>${e(s.scope)}</p></li>`).join('')}</ol><p class="company-status-review-scope">${e(neuroCompanyStatusData.scope)} <a href="./data/company-status.json" download>Download this evidence snapshot ↓</a></p></details></section>`; }
    return { get, render };
})();
